CREATE OR REPLACE FUNCTION public.ai_finance_validate_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF array_ndims(NEW.thresholds) IS DISTINCT FROM 1 OR array_lower(NEW.thresholds,1) IS DISTINCT FROM 1 OR cardinality(NEW.thresholds)<>3 OR NEW.thresholds[1]<1 OR NEW.thresholds[1]>=NEW.thresholds[2] OR NEW.thresholds[2]>=NEW.thresholds[3] OR NEW.thresholds[3]>100 OR array_position(NEW.thresholds,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Faixas inválidas'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.ai_finance_validate_settings() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.ai_finance_block(_brand uuid,_provider text,_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _generation bigint; _label text; _body text; BEGIN IF _provider IS NULL OR _reason IS NULL OR _provider NOT IN ('openai','anthropic','gemini','groq') OR _reason NOT IN ('provider_credit','provider_financial_limit') THEN RAISE EXCEPTION 'Estado inválido'; END IF; _label=CASE _provider WHEN 'openai' THEN 'OpenAI' WHEN 'anthropic' THEN 'Anthropic' WHEN 'gemini' THEN 'Gemini' WHEN 'groq' THEN 'Groq' END; _body=CASE _reason WHEN 'provider_credit' THEN 'Créditos insuficientes na '||_label||'. Solicite ao administrador a reposição do saldo para continuar.' ELSE 'Limite financeiro atingido na '||_label||'. Solicite ao administrador a revisão do limite no provedor para continuar.' END; INSERT INTO public.ai_provider_finance(brand_id,provider,blocked,reason,generation) VALUES(_brand,_provider,true,_reason,1) ON CONFLICT(brand_id,provider) DO UPDATE SET blocked=true,reason=excluded.reason,generation=ai_provider_finance.generation+CASE WHEN ai_provider_finance.blocked THEN 0 ELSE 1 END,updated_at=now() RETURNING generation INTO _generation; PERFORM public.ai_finance_notify(_brand,'provider:'||_provider||':'||_generation,'Disponibilidade financeira de IA: '||_label,_body); END $$;
REVOKE ALL ON FUNCTION public.ai_finance_block(uuid,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ai_finance_block(uuid,text,text) TO service_role;